package main

import (
	"fmt"
	"os"

	"syscli/platform"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Println("Usage: syscli <command>")
		fmt.Println("")
		fmt.Println("Available commands:")
		fmt.Println("  info    Show system and platform information")
		fmt.Println("  getpid  Print the current process ID")
		os.Exit(0)
	}

	switch os.Args[1] {
	case "info":
		info, err := platform.SysInfo()
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		fmt.Println(info)

	case "getpid":
		pid, err := platform.GetPID()
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		fmt.Println(pid)

	default:
		fmt.Fprintf(os.Stderr, "Unknown command: %s\n", os.Args[1])
		os.Exit(1)
	}
}

package platform

import "fmt"

// SysInfo returns a human-readable string describing the system and platform.
func SysInfo() (string, error) {
	arch, err := Arch()
	if err != nil {
		return "", err
	}
	version, err := OSVersion()
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("Platform: %s\nArchitecture: %s\nOS Version: %s", OS(), arch, version), nil
}

//go:build linux

package platform

import (
	"fmt"
	"runtime"

	"golang.org/x/sys/unix"
)

func OS() string {
	return "Linux"
}

func Arch() (string, error) {
	return runtime.GOARCH, nil
}

func OSVersion() (string, error) {
	var uts unix.Utsname
	if err := unix.Uname(&uts); err != nil {
		return "", fmt.Errorf("uname: %w", err)
	}
	return fmt.Sprintf("%s %s", unix.ByteSliceToString(uts.Release[:]), unix.ByteSliceToString(uts.Machine[:])), nil
}

func GetPID() (int, error) {
	return unix.Getpid(), nil
}

